  "abby": {label:"アビー",kanji:"",roma:"abii", ex5:[{t:1,s:"アビーは学校で一番の親友だ。"},{t:2,s:"昨日アビーと図書館に行った。"},{t:3,s:"アビーはピアノを弾くのがとても上手だ。"},{t:4,s:"アビーが遊びに来る。"},{t:5,s:"アビーと一緒に勉強する。"}]},
