  "abdomen": {label:"腹部",kanji:"腹部",roma:"fukubu", ex5:[{t:1,s:"腹部が痛む。"},{t:2,s:"腹部が張っている感じがする。"},{t:3,s:"医者が腹部を診察した。"},{t:4,s:"腹部に違和感がある。"},{t:5,s:"腹部を保護する。"}]},
