  "abducting": {label:"誘拐している",kanji:"誘拐している",roma:"yuukaishteiru", ex5:[{t:1,s:"悪党が王女を誘拐しているところを捕まった。"},{t:2,s:"映画は宇宙人が人々を誘拐している話だ。"},{t:3,s:"彼はビジネスマンを誘拐した罪で逮捕された。"},{t:4,s:"誘拐している現場を目撃した。"},{t:5,s:"子供を誘拐している男がいた。"}]},
