  "abilities": {label:"能力",kanji:"能力",roma:"nōryoku", ex5:[{t:1,s:"彼女の能力が輝いている。"},{t:2,s:"彼の能力は稀なものだ。"},{t:3,s:"私たちは彼らの能力をテストする。"},{t:4,s:"能力を発揮するチャンスだ。"},{t:5,s:"個々の能力を尊重する。"}]},
