  "abject": {label:"みじめな",kanji:"惨めな",roma:"mijime na", ex5:[{t:1,s:"家族はみじめな貧困生活を送っていた。"},{t:2,s:"彼はみじめな言い訳をした。"},{t:3,s:"計画はみじめな失敗に終わった。"},{t:4,s:"みじめな気分で家に帰った。"},{t:5,s:"みじめな結末を迎えた。"}]},
  "abjectly": {label:"ひくつに",kanji:"卑屈に",roma:"hikutsu ni", ex5:[{t:1,s:"彼はミスをひくつに謝った。"},{t:2,s:"彼女はひくつに振る舞った。"},{t:3,s:"ひくつに生きる必要はない。"},{t:4,s:"彼はひくつに頼み込んだ。"},{t:5,s:"ひくつに頭を下げた。"}]},
