  "ablation": {label:"アブレーション",kanji:"",roma:"aburēshon", ex5:[{t:1,s:"医師は不整脈の治療に心筋アブレーションを勧めた。"},{t:2,s:"レーザーアブレーションは現代の眼科手術で一般的だ。"},{t:3,s:"アブレーションの手術後、彼はすぐに回復した。"},{t:4,s:"心臓のアブレーションを受けた。"},{t:5,s:"アブレーションは有効な治療法だ。"}]},
